/**
 * Event.ts
 *
 * Type definitions for the in-game event / court petition system.
 * Events are discrete player decision points generated by the simulation engine.
 */

export type EventType =
  | 'COURT_PETITION'
  | 'DEATH'
  | 'BIRTH'
  | 'REVOLT'
  | 'PLAGUE'
  | 'FAMINE'
  | 'WAR_DECLARATION'
  | 'ALLIANCE_OFFER'
  | 'DIPLOMATIC_INCIDENT'
  | 'RELIGIOUS_CRISIS'
  | 'NATURAL_DISASTER'
  | 'ASSASSINATION_ATTEMPT'
  | 'CONSPIRACY_REVEALED'
  | 'SUCCESSION_CRISIS'
  | 'TRADE_OPPORTUNITY'
  | 'MERCENARY_OFFER';

export type EventChoiceAction =
  | 'SPEND_GOLD'
  | 'GAIN_GOLD'
  | 'GAIN_PRESTIGE'
  | 'LOSE_PRESTIGE'
  | 'ACCEPT'
  | 'DECLINE'
  | 'REFUSE'
  | 'IGNORE'
  | 'EXECUTE'
  | 'PARDON'
  | 'RECRUIT';

export interface EventChoice {
  label: string;
  action: EventChoiceAction | string;
  amount?: number;
  effect: string;
}

export interface GameEvent {
  id: string;
  type: EventType | string;
  title: string;
  description: string;
  createdYear: number;
  createdDay: number;
  /** Optional character the event is about */
  characterId?: string;
  /** Optional province the event is anchored to */
  provinceId?: string;
  choices: EventChoice[];
  /** Whether the event has already been resolved */
  resolved?: boolean;
}
